private deliverInboxNotice(agent: Agent, member: AgentTeamAgentMember, cause: NotificationCause, sequenced = false): void {
  const notifications = this.requireLedger().notificationFacts(member.memberId)
  const mainNotifications = this.requireLedger().mainNotificationFacts(member.memberId)
  const scope = this.memberScope(member.memberId, agent.id)
  const causeText = this.notificationCauseText(cause)
  if (notifications.length === 0 && mainNotifications.length === 0) {
    this.dropInboxCoverage(member.memberId)
    this.ctx.logger.debug(`agent-team: Team Inbox notice not attempted for ${scope} cause ${causeText}: the Member has no unread Team facts`)
    return
  }
  // Any ordinary next-turn input already queued (a rollover's or recovery's
  // carried messages) forces sequencing regardless of the caller: a steer
  // would claim the nearest step boundary and leapfrog the carried turn.
  if (!sequenced) {
    sequenced = agent.inbox.nextTurn.some(message => message.source.kind === 'user')
  }
  const previous = this.inboxNoticeDeliveries.get(member.memberId)
  const plan = this.inboxDeliveryPlan(member.memberId, notifications, mainNotifications, previous)
  const facts = this.notificationIdentity(notifications, mainNotifications)
  // An unchanged rederivation spends no attempt: the delivery already made
  // for these facts stands, which is what keeps a repeated commit's logging
  // bounded.
  if (plan.trigger === undefined) {
    this.ctx.logger.debug(`agent-team: Team Inbox notice not attempted for ${scope} cause ${causeText}: ${plan.signature === ''
      ? `only ordinary Thread updates below the threshold of ${INBOX_THRESHOLD_UPDATES} remain (${facts})`
      : `the same unread facts (${facts}) already have a delivery attempt`}`)
    return
  }
  const pending = [...agent.inbox.nextStep, ...agent.inbox.nextTurn]
  // steerResume already combines the recovery instruction and these durable
  // facts. Its synchronous running transition must not replace that notice.
  if (pending.some(message => this.isRecoveryNotice(message))) {
    this.coverInboxFacts(member.memberId, plan)
    this.ctx.logger.info(`agent-team: Team Inbox notice carried by the queued recovery instruction for ${scope} cause ${causeText} (${facts}): queued with that recovery instruction, not yet read by the model`)
    return

const existingInboxHint = pending.find(message => this.isInboxNotice(message))
if (existingInboxHint !== undefined) this.removeExpectedTeamWake(agent, existingInboxHint)
const notice = this.notificationText(notifications, member.memberId, mainNotifications)
const hint = createUserMessage({
  content: [{ type: 'text', text: notice.text }],
  source: { kind: AGENT_TEAM_PLUGIN_ID, form: 'notice', summary: TEAM_INBOX_NOTICE_SUMMARY },
})
this.trackTeamWake(agent, hint)
const recordedPlan: InboxDeliveryPlan = { ...plan, summarizedThrough: new Map([...plan.summarizedThrough].filter(([threadRef]) => notice.renderedThreads.has(threadRef))) }
const attempt = this.beginInboxDelivery(member.memberId, recordedPlan)
try {
  // Steer normally claims the nearest step boundary — which would
  // preempt carried input that a swap or crash recovery queued as
  // ordinary next-turn messages. The sequenced mode enqueues the
  // rederived Inbox as its own follow-up turn instead, so the delivery
  // order stays carried input → rederived Inbox.
  if (sequenced) agent.followup(hint)
  else agent.steer(hint)
} catch (error) {
  this.dropInboxCoverage(member.memberId, previous?.summarizedThrough ?? new Map())
  if (error instanceof AgentTeamInvariantError) throw error
  this.ctx.logger.warn(`agent-team: Team Inbox notice delivery failed for ${scope} cause ${causeText} attempt ${attempt} (${facts}): ${failureDetail(error)}; the operation is committed and stands, and the failed delivery stands as an attempt so the next fact touching this Member rederives and retries it`)
  return
}
this.ctx.logger.info(`agent-team: Team Inbox notice queued for ${scope} cause ${causeText} attempt ${attempt} delivery ${plan.trigger} lane '${sequenced ? 'follow-up turn' : 'next step'}' (${facts}): queued for the Member's next step, not yet read by the model`)

private inboxCandidateThreads(memberId: AgentTeamMemberId): Iterable<AgentTeamThreadRef> {
  const refs = new Set<AgentTeamThreadRef>()
  for (const source of [this.state.attentionThreadsByMember.get(memberId), this.state.directMarkersByMember.get(memberId), this.state.activityMarkersByMember.get(memberId), this.state.reminderMarkersByMember.get(memberId)]) {
    for (const threadRef of source?.keys() ?? []) refs.add(threadRef)
  }
  return refs
}

/** Model-visible notification material derived from the recipient's current durable unread state. */
notificationFacts(memberId: AgentTeamMemberId, request?: AgentTeamInboxRequest): readonly {
  readonly item: AgentTeamInboxItem
  readonly facts: readonly AgentTeamThreadReadFact[]
  readonly reminders: readonly import('./types/requests-results.ts').AgentTeamInboxReminder[]
}[] {
  const member = this.requireMember(memberId)
  if (request !== undefined && !this.participatesIn(memberId, request.workspaceId)) throw new Error('Member cannot inspect another Workspace')
  const actor = { kind: 'member' as const, memberId, handle: member.handle }
  const inbox = request === undefined ? this.memberInbox(actor, {}) : this.inbox(actor, request)
  return Object.freeze(inbox.items.map(item => Object.freeze({ item,
    facts: this.unreadFor(memberId, item.thread.threadRef), reminders: item.reminders })))
}

readThread(request: AgentTeamAuthorizedThreadReadRequest): Promise<AgentTeamThreadReadOutcome> {
  return this.enqueue(async () => {
    const existing = this.state.byRequest.get(request.requestId)
    if (existing !== undefined) {
      this.assertSameThreadRead(existing, request)
      const current = this.prepareRead(existing.data.memberId, existing.data.workspaceId, request)
      return Object.freeze({ value: Object.freeze({ receipt: this.receipt(existing), ...this.readPicture(current) }), committed: false })
    }
    const actor = this.assertActorForWorkspace(request.actor, request.workspaceId)
    const prepared = this.prepareRead(actor.memberId, request.workspaceId, request)
    // A read whose Inbox delta is empty writes nothing: the watermark does
    // not advance and no marker is consumed. It answers with the same picture
    // and no receipt, so the caller learns "no operation" from the result's
    // committed flag, never from a sequence this read did not write.
    if (isEmptyInboxDelta(prepared.inbox)) return Object.freeze({ value: this.readPicture(prepared), committed: false })
    // The record carries progress, not the picture: the Thread, its facts,
    // the anchor and the reader's Attention are projection state every replay
    // already holds.
    const data: AgentTeamThreadReadReceipt = Object.freeze({ workspaceId: request.workspaceId, memberId: actor.memberId,
      threadRef: prepared.thread.threadRef, ...(prepared.task === undefined ? {} : { taskRef: prepared.task.taskRef }),
      readThroughSequence: prepared.readThroughSequence, inbox: prepared.inbox })
    const operation: AgentTeamThreadReadOperation = Object.freeze({
      ...this.operationBase(request, this.nextSequence()), kind: 'team/thread-read', data,
    })
    await this.table.put(operation.operationId, operation)
    this.applyAndAdvanceProjectionVersion(operation)
    return Object.freeze({ value: Object.freeze({ receipt: this.receipt(operation), ...this.readPicture(prepared) }), committed: true })
  })

