124	function storedPool(records: Array<[string, unknown]>, version: number = agentTeamDomainSpec.version): MemoryMediaPool {
125	  const pool = new MemoryMediaPool()
126	  pool.versions.set('agent_team', version)
127	  pool.media.set('agent_team', { tables: new Map([['operations', new Map(records)]]), global: null })
128	  return pool
129	}
130	
131	function committed<T extends { readonly kind: string }>(result: T): Extract<T, { readonly kind: 'committed' }> {
132	  if (result.kind !== 'committed') throw new Error(`expected committed result, received ${result.kind}`)
133	  return result as Extract<T, { readonly kind: 'committed' }>
134	}
135	
136	function withTask<T extends { readonly task?: AgentTeamTask }>(result: T): T & { readonly task: AgentTeamTask } {
137	  if (result.task === undefined) throw new Error('expected Task overlay')
138	  return result as T & { readonly task: AgentTeamTask }
139	}
140	
141	function ledgerAtBoot(test: TeamHarness): AgentTeamLedger {
142	  return new AgentTeamLedger(test.facility.get('agent_team')!.table('operations') as unknown as KvTable<AgentTeamOperationId, AgentTeamOperation>)
143	}
