145	async function addLedgerMember(
146	  ledger: AgentTeamLedger,
147	  projectRef: string | undefined,
148	  memberId = `member:agent-${crypto.randomUUID()}`,
149	  description = 'Test Agent',
150	  handle = memberId.slice('member:'.length),
151	): Promise<{ readonly member: AgentTeamAgentMember; readonly actor: AgentTeamMemberActor }> {
