cat > /tmp/fix_imports.py <<'PYEOF'
import os, re
d='scripts/e2e'
# node + vitest values a scenario body may reference
NEED = {
 'join': "import { join } from 'node:path'",
 'expect': "import { expect } from 'vitest'",
 'it': "import { it } from 'vitest'",
 'writeFile': "import { writeFile } from 'node:fs/promises'",
 'readFile': "import { readFile } from 'node:fs/promises'",
 'mkdtemp': "import { mkdtemp } from 'node:fs/promises'",
 'tmpdir': "import { tmpdir } from 'node:os'",
 'Buffer': None,
}
for f in sorted(os.listdir(d)):
    if not f.endswith('.e2e.ts'): continue
    p=os.path.join(d,f); src=open(p,encoding='utf-8').read()
    # body = everything after the last import line at top
    lines=src.split('\n')
    hdr_end=0
    for i,l in enumerate(lines):
        if l.startswith('import ') or l.startswith('// Runs') or l.strip()=='' or l.startswith(' * ') or l.startswith('/**') or l.startswith(' */'):
            hdr_end=i+1
        else:
            break
    body='\n'.join(lines[hdr_end:])
    adds=[]
    for name,imp in NEED.items():
        if imp is None: continue
        if re.search(r'\b'+name+r'\b', body):
            # is it imported anywhere already?
            if not re.search(r"import \{[^}]*\b"+name+r"\b[^}]*\} from", src):
                adds.append(imp)
    if adds:
        # merge vitest imports
        vitest=[a for a in adds if "from 'vitest'" in a]
        others=[a for a in adds if "from 'vitest'" not in a]
        if vitest:
            names=[]
            for a in vitest:
                m=re.match(r"import \{ ([^}]*) \} from 'vitest'", a); names += [x.strip() for x in m.group(1).split(',')]
            existing=re.search(r"import \{ ([^}]*) \} from 'vitest'", src)
            if existing:
                cur=[x.strip() for x in existing.group(1).split(',') if x.strip()]
                for n in names:
                    if n not in cur: cur.append(n)
                src=src[:existing.start()]+"import { "+", ".join(cur)+" } from 'vitest'"+src[existing.end():]
            else:
                src = "import { "+", ".join(names)+" } from 'vitest'\n" + src
        if others:
            src = src.rstrip('\n') + '\n' + '\n'.join(others) + '\n'
        open(p,'w',encoding='utf-8').write(src)
        print('added', adds, '->', f)
PYEOF
