import os, re
d='scripts/e2e'
for f in sorted(os.listdir(d)):
    if not (f.endswith('.e2e.ts') or f=='support.ts'): continue
    p=os.path.join(d,f); src=open(p,encoding='utf-8').read()
    # merge the value-import lines that belong to one module into a single statement
    mods = {}
    order = []
    lines = src.split('\n')
    out=[]
    pending = {}
    def flush():
        global pending
        for mod, names in pending.items():
            out.append("import { " + ", ".join(names) + " } from '" + mod + "'")
        pending = {}
    for l in lines:
        m = re.match(r"import \{ ([^}]*) \} from '([^']+)'$", l)
        if m and not l.startswith('import type'):
            mod = m.group(2)
            names = [x.strip() for x in m.group(1).split(',') if x.strip()]
            if mod in pending:
                for n in names:
                    if n not in pending[mod]: pending[mod].append(n)
            else:
                pending[mod] = names
            continue
        if l.strip()=='' and pending and out and out[-1].startswith('import {'):
            flush(); out.append(l); continue
        if l.startswith('import ') or l.startswith('//'):
            flush(); out.append(l); continue
        flush(); out.append(l)
    flush()
    open(p,'w',encoding='utf-8').write('\n'.join(out))
    print('tidied', f)
PYEOF
